        { name: "Purifyre", type: "A3", icon: "skill_icons/Artak_A3.png", description_en: "Attacks all enemies 2 times. The first hit has a 75% chance of placing a [HP Burn] debuff on all enemies for 2 turns.\n\nRestores this Champion’s destroyed MAX HP by 10% for each [HP Burn] debuff placed by this skill. Heals this Champion by 5% of their MAX HP for each [HP Burn] debuff attempt blocked or resisted by the enemy team.", cooldown: 4, multiplier: "0.14*HP", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Buff/Debuff Chance +10%", "Lvl. 4 Buff/Debuff Chance +15%", "Lvl. 5 Cooldown -1"] },
        { name: "Burning Blood", type: "Passif", icon: "skill_icons/Artak_Passif.png", description_en: "Whenever a [HP Burn] debuff is activated, destroys this Champion’s MAX HP by 5%. Stacks up to 50%. Increases this Champion’s DMG, C. DMG, and DEF by 1% for each 1% of their destroyed MAX HP. Also increases this Champion’s SPD and RES by 2 for each 1% of their destroyed MAX HP.", cooldown: 0, multiplier: null, upgrades: [] }
