        { name: "Verglas Wave", type: "A2", icon: "skill_icons/Cécilia Rouge espoir_A2.png", description_en: "Attacks all enemies 2 times. The damage dealt by this skill increases by 5% for each ally above 50% HP.\n\nPlaces a [Perfect Veil] buff on all allies except this Champion for 2 turns.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Cooldown -1", "Lvl. 4 Cooldown -1"] },
        { name: "Yuletide Abeyance", type: "A3", icon: "skill_icons/Cécilia Rouge espoir_A3.png", description_en: "Attacks all enemies. Before attacking, places a 60% [Increase DEF] buff on all allies for 2 turns.\n\nPlaces a 25% [Strengthen] buff and a [Counterattack] buff on all allies for 2 turns.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Cooldown -1", "Lvl. 4 Cooldown -1"] },
        { name: "Spirit Of Giving", type: "Passif", icon: "skill_icons/Cécilia Rouge espoir_Passif.png", description_en: "[Active Effect]\n\nPlaces a [Revive on Death] buff for 1 turn on an ally when that ally’s HP falls below 50%. If there are multiple Champions on the team with this skill, only one will activate. This skill will not activate on duplicate copies of this Champion, if this particular Champion is dead.\n\n[Passive Effect]\n\nAt the start of this Champion’s turn, removes one random debuff from a random ally and fills their Turn Meter by 10%.", cooldown: 6, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1"] }
