        { name: "Butcher's Glee", type: "A2", icon: "skill_icons/Candraphon_A2.png", description_en: "Attacks all enemies.\n\nGrants an Extra Turn and resets the cooldown of the {On the Hunt} skill if this attack kills an enemy.", cooldown: 4, multiplier: "3.7*ATK", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Damage +5%", "Lvl. 4 Damage +5%", "Lvl. 5 Damage +5%", "Lvl. 6 Cooldown -1"] },
        { name: "On the Hunt", type: "A3", icon: "skill_icons/Candraphon_A3.png", description_en: "Places a [Perfect Veil] buff, a 50% [Increase ATK] buff, a 30% [Increase SPD] buff, and a 30% [Increase C. DMG] buff on this Champion for 2 turns.", cooldown: 5, multiplier: null, upgrades: [] },
        { name: "From the Shadows", type: "Passif", icon: "skill_icons/Candraphon_Passif.png", description_en: "[Passive Effect]\n\nDamage increases by 40% while attacking under a [Veil] or [Perfect Veil] buff. Receives 40% less damage while under a [Veil] or [Perfect Veil] buff. Also boosts this Champion's Turn Meter by 15% each time this Champion receives damage under a [Veil] or [Perfect Veil] buff. Does not work if this Champion is the only alive ally on the team.\n\n[Active Effect]\n\nPlaces a [Perfect Veil] buff on this Champion for 1 turn each time an enemy's Turn Meter is filled. This buff cannot be removed.", cooldown: 0, multiplier: null, upgrades: [] }
