        { name: "Flurry of Petals", type: "A2", icon: "skill_icons/Dame Kimi_A2.png", description_en: "Attacks all enemies. Has a 75% chance of placing a 50% [Decrease ACC] debuff and a 30% [Decrease SPD] debuff for 2 turns. Also has a 75% chance of decreasing each target's Turn Meter by 15%.", cooldown: 4, multiplier: "4.2*ATK", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Damage +5%", "Lvl. 4 Buff/Debuff Chance +10%", "Lvl. 5 Buff/Debuff Chance +15%", "Lvl. 6 Cooldown -1"] },
        { name: "Spirit Flux", type: "A3", icon: "skill_icons/Dame Kimi_A3.png", description_en: "Removes one random buff from each enemy, then has a 75% chance of placing a [Block Buffs] debuff for 2 turns on enemies who have buffs removed.\n\nAlso fills the Turn Meters of all allies by 15% and places a 50% [Increase ACC] buff and a 30% [Increase SPD] buff on all allies for 2 turns.", cooldown: 6, multiplier: null, upgrades: ["Lvl. 2 Buff/Debuff Chance +10%", "Lvl. 3 Buff/Debuff Chance +15%", "Lvl. 4 Cooldown -1", "Lvl. 5 Cooldown -1"] },
        { name: "Imperious", type: "Passif", icon: "skill_icons/Dame Kimi_Passif.png", description_en: "Whenever this Champion places a debuff on an enemy, also decreases that enemy's Turn Meter by 5% for each debuff placed.\n\nWhenever this Champion or an ally receives a debuff, fill their Turn Meter by 5% for each debuff received.", cooldown: 0, multiplier: null, upgrades: [] }
