        { name: "Culler of the Weak", type: "A2", icon: "skill_icons/Gracchos Viré-drake_A2.png", description_en: "Attacks all enemies 2 times.\n\nEach hit will ignore 25% DEF against targets with less than 50% HP. The first hit has a 75% chance of placing a 60% [Decrease DEF] debuff on each enemy for 2 turns. The second hit has a 75% chance of placing a [Block Buffs] debuff on each enemy for 2 turns. Each hit will ignore 25% RES against targets with less than 50% HP.", cooldown: 4, multiplier: "0.15*HP", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Damage +10%", "Lvl. 4 Buff/Debuff Chance +10%", "Lvl. 5 Buff/Debuff Chance +15%", "Lvl. 6 Cooldown -1"] },
        { name: "Dragonkin Warcry", type: "A3", icon: "skill_icons/Gracchos Viré-drake_A3.png", description_en: "Places a 60% [Increase DEF] buff on all allies for 2 turns. Also places a [Block Damage] buff on all allies for 1 turn.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1"] },
        { name: "Ferocious Ambition", type: "Passif", icon: "skill_icons/Gracchos Viré-drake_Passif.png", description_en: "If an ally has more than 50% HP and is under any buffs placed by this Champion, that ally deals 10% more damage. If an ally has less than 50% HP and is attacked by an enemy under any debuffs placed by this Champion, that ally receives 10% less damage. If there are multiple Champions on the team with this skill, only one will activate.", cooldown: 0, multiplier: null, upgrades: [] }
