        { name: "Juggernaut", type: "A3", icon: "skill_icons/Turvold_A3.png", description_en: "Attacks 1 enemy 2 times. Damage increases according to the number of buffs on this Champion. If the target is killed, resets the cooldown of this skill.", cooldown: 5, multiplier: "3*ATK", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Damage +10%", "Lvl. 4 Cooldown -1", "Lvl. 5 Damage +10%", "Lvl. 6 Cooldown -1"] }
