        { name: "Stand Firm", type: "A2", icon: "skill_icons/Valkyrie_A2.png", description_en: "Attacks all enemies. Places a [Shield] buff on all allies for 3 turns and a [Counterattack] buff on all allies for 2 turns. The value of the [Shield] and the damage inflicted are proportional to this Champion's DEF.", cooldown: 4, multiplier: "3*DEF", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Shield +10%", "Lvl. 4 Damage +5%", "Lvl. 5 Shield +10%", "Lvl. 6 Damage +10%", "Lvl. 7 Cooldown -1"] },
        { name: "Jealousy", type: "Passif", icon: "skill_icons/Valkyrie_Passif.png", description_en: "This Champion's Turn Meter will be increased by 10% each time an enemy Champion places a buff. Enemy Champions will have their Turn Meters decreased by 10% for each buff they receive.", cooldown: 0, multiplier: null, upgrades: [] }
