        { name: "Mercy of the Oasis", type: "A3", icon: "skill_icons/Belletar Tue-mages_A3.png", description_en: "Revives all dead allies with 50% HP and 50% Turn Meter, then places a [Shield] buff on all revived allies for 2 turns, equal to 20% of this Champion's MAX HP. Also places a [Block Debuffs] buff on all allies for 2 turns.", cooldown: 6, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1"] },
        { name: "Critical Juncture", type: "Passif", icon: "skill_icons/Belletar Tue-mages_Passif.png", description_en: "Has a 75% chance of decreasing all of an ally's skill cooldowns by 1 turn whenever they are revived.\n\nOnce per turn, if an ally is killed, reduces the cooldowns of all this Champion's skills by 1 turn.", cooldown: 0, multiplier: null, upgrades: ["Lvl. 2 Buff/Debuff Chance +10%", "Lvl. 3 Buff/Debuff Chance +15%"] }
