        { name: "Didn't Need 'Em", type: "Passif", icon: "skill_icons/Chevalier Suprême_Passif.png", description_en: "Increases this Champion’s HP, DEF, and SPD by 10% for each dead ally.", cooldown: 0, multiplier: null, upgrades: [] }
