        { name: "Death's Balance", type: "A3", icon: "skill_icons/Dreng La Tombe_A3.png", description_en: "Equalizes the HP of all allies, then attacks 1 enemy.\n\nThe HP levels of all allies will be brought up to the level of the ally with the highest HP.\n\nThe attack will ignore 30% of the target's DEF if the target's current HP is equal to or lower than this Champion's current HP.\n\nWill decrease the cooldown of the {Exalted Pyre} skill by 1 turn if the target's current HP is higher than this Champion's current HP.", cooldown: 5, multiplier: "0.35*HP", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Damage +10%", "Lvl. 4 Cooldown -1"] },
        { name: "Fortress", type: "Passif", icon: "skill_icons/Dreng La Tombe_Passif.png", description_en: "Reflects 30% of the damage this Champion receives back to the attacker if this Champion has 50% HP or more.\n\nDeals 30% more damage instead if this Champion has less than 50% HP.", cooldown: 0, multiplier: null, upgrades: [] }
