        { name: "Fiery Blood", type: "Passif", icon: "skill_icons/Drexthar Doublesang_Passif.png", description_en: "Has a 55% chance of placing a [HP Burn] debuff for 2 turns on the attacker when hit. This Champion’s RES increases by 10 for every enemy under a [HP Burn] debuff. Stacks up to 50.", cooldown: 0, multiplier: null, upgrades: ["Lvl. 2 Buff/Debuff Chance +5%", "Lvl. 3 Buff/Debuff Chance +5%", "Lvl. 4 Buff/Debuff Chance +10%"] }
