        { name: "Earthdancer", type: "A2", icon: "skill_icons/Esmé la Danseuse_A2.png", description_en: "Attacks all enemies.\n\nHas a 75% chance of placing a 25% [Weaken] debuff and a [Block Buffs] debuff for 2 turns.\n\nAlso decreases the Turn Meters of all enemies by 20%. If {{Modo of the Peal}} is on the same team, steals 20% of each enemy’s Turn Meter instead.", cooldown: 4, multiplier: "4.5*ATK", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Buff/Debuff Chance +10%", "Lvl. 4 Buff/Debuff Chance +15%", "Lvl. 5 Cooldown -1"] },
        { name: "Blessing of the Sands", type: "A3", icon: "skill_icons/Esmé la Danseuse_A3.png", description_en: "Places a 50% [Increase ACC] buff and a 30% [Increase SPD] buff on all allies for 2 turns.\n\nHas a 75% chance of removing all buffs from all enemies. If {{Modo of the Peal}} is on the same team, has a 75% chance of stealing all buffs from all enemies instead.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Buff/Debuff Chance +10%", "Lvl. 3 Buff/Debuff Chance +15%", "Lvl. 4 Cooldown -1"] },
        { name: "Beguiling Moves", type: "Passif", icon: "skill_icons/Esmé la Danseuse_Passif.png", description_en: "[Passive Effect]\n\nWhen hit, has a 15% chance of randomly changing the attacker’s critical hits to weak, normal, or strong hits. If {{Modo of the Peal}} is on the same team, the chance increases to 30%.\n\n[Active Effect]\n\nWhenever this Champion is hit, increases the Turn Meter of the ally with the highest ATK by 50%.", cooldown: 0, multiplier: null, upgrades: [] }
