        { name: "Canticle of Cold", type: "A2", icon: "skill_icons/Karilon le Sonneur_A2.png", description_en: "Attacks all enemies. Has a 75% chance of placing a [Hex] debuff and a 25% [Weaken] debuff for 2 turns.\n\nIf the target is under a [Freeze] debuff, has a 75% chance of placing a [Hex] debuff and a 25% [Weaken] debuff for 3 turns instead.", cooldown: 3, multiplier: "3.2*ATK", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Buff/Debuff Chance +10%", "Lvl. 4 Damage +10%", "Lvl. 5 Buff/Debuff Chance +15%"] },
        { name: "Polar Vortex", type: "A3", icon: "skill_icons/Karilon le Sonneur_A3.png", description_en: "Places a [Freeze] debuff on all enemies for 1 turn.\n\nFully depletes the Turn Meters of all enemies that receive [Freeze] debuffs from this skill.\n\nFills the Turn Meters of all allies by 10% for each [Freeze] debuff attempt blocked or resisted by the enemy team.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1"] },
        { name: "Rime Hammer", type: "Passif", icon: "skill_icons/Karilon le Sonneur_Passif.png", description_en: "Allies will ignore 10% of the target's DEF if the target is under [Freeze] debuffs.\n\nIf the [Freeze] debuff was placed by this Champion, allies will ignore 20% of the target's DEF instead.", cooldown: 0, multiplier: null, upgrades: [] }
