        { name: "Soul Shepherd", type: "A2", icon: "skill_icons/Mère Cybèle_A2.png", description_en: "Places a [Revive On Death] buff and a 60% [Increase DEF] buff on all allies for 2 turns.", cooldown: 6, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1", "Lvl. 4 Cooldown -1"] },
        { name: "Uncanny Transfer", type: "A3", icon: "skill_icons/Mère Cybèle_A3.png", description_en: "Swaps HP with an ally.\n\nIf this Champion's HP is equal to or higher than the target's HP after the swap, fills this Champion's Turn Meter by 40%, places a 30% [Increase SPD] buff on this Champion for 2 turns, and places a [Block Damage] buff on the target ally for 1 turn. If this Champion's HP is lower than the target's HP after the swap, fills the target's Turn Meter by 40%, places a 30% [Increase SPD] buff on them for 2 turns, and places a [Block Damage] buff on this Champion for 1 turn. Also places 2 15% [Continuous Heal] buffs on this Champion for 2 turns.", cooldown: 6, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1", "Lvl. 4 Cooldown -1"] },
        { name: "Gravewalker", type: "Passif", icon: "skill_icons/Mère Cybèle_Passif.png", description_en: "Fully heals the ally with the lowest HP whenever this Champion is killed.\n\nHeals all allies by 20% of their MAX HP and fills their Turn Meters by 15% whenever this Champion is revived.", cooldown: 0, multiplier: null, upgrades: [] }
