        { name: "Ancestral Spirits", type: "A3", icon: "skill_icons/Néspectre_A3.png", description_en: "Attacks all enemies. Has a 75% chance of placing a 60% [Decrease DEF] debuff for 2 turns. This debuff cannot be resisted. Also places a 50% [Increase ATK] buff on all allies for 2 turns.", cooldown: 5, multiplier: "3.8*ATK", upgrades: ["Lvl. 2 Buff/Debuff Chance +10%", "Lvl. 3 Buff/Debuff Chance +15%", "Lvl. 4 Cooldown -1"] }
