        { name: "Radiant Suffering", type: "A2", icon: "skill_icons/Tuhanarak_A2.png", description_en: "Attacks 1 enemy. Has a 75% chance of placing a 50% [Decrease ATK] debuff and a [Block Buffs] debuff for 2 turns. Also applies a [Debuff Spread] effect, taking 2 random debuffs from the target and placing them on all enemies.", cooldown: 4, multiplier: "5.6*DEF", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Damage +5%", "Lvl. 4 Buff/Debuff Chance +10%", "Lvl. 5 Buff/Debuff Chance +15%", "Lvl. 6 Cooldown -1"] },
        { name: "Desert Fitness", type: "A3", icon: "skill_icons/Tuhanarak_A3.png", description_en: "Places a 60% [Increase DEF] buff and a 30% [Increase SPD] buff on all allies for 2 turns.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1"] },
        { name: "Inviolable", type: "Passif", icon: "skill_icons/Tuhanarak_Passif.png", description_en: "Removes 1 random debuff from all allies at the start of each turn.\n\nRemoves 2 random debuffs instead from allies under [Continuous Heal] buffs.", cooldown: 0, multiplier: null, upgrades: [] }
