        { name: "Infernal Minions", type: "A3", icon: "skill_icons/Tyran Ixlimor_A3.png", description_en: "Places a 50% [Ally Protection] buff on all allies except this Champion for 2 turns. Places a 60% [Increase DEF] buff on all allies for 2 turns.", cooldown: 4, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1"] },
        { name: "Fires of Doom", type: "Passif", icon: "skill_icons/Tyran Ixlimor_Passif.png", description_en: "Decreases damage inflicted by enemies under [HP Burn] debuffs by 10%.", cooldown: 0, multiplier: null, upgrades: [] }
