        { name: "Thornchain Malison", type: "A2", icon: "skill_icons/Arix_A2.png", description_en: "Attacks all enemies. Has a 50% chance of placing a [Stun] debuff for 1 turn. Transfers a random debuff from this Champion to the targets that receive [Stun] debuffs from this skill.", cooldown: 4, multiplier: "0.35*HP", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Buff/Debuff Chance +10%", "Lvl. 4 Damage +10%", "Lvl. 5 Buff/Debuff Chance +15%", "Lvl. 6 Cooldown -1"] },
        { name: "Warped Guidance", type: "A3", icon: "skill_icons/Arix_A3.png", description_en: "Places a 50% [Ally Protection] buff on all allies except this Champion for 2 turns. Also places a [Counterattack] buff on this Champion for 2 turns.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1", "Lvl. 3 Cooldown -1"] },
        { name: "Cynical", type: "Passif", icon: "skill_icons/Arix_Passif.png", description_en: "Fills this Champion’s Turn Meter by 5% each time an ally inflicts a critical hit.\n\nHeals this Champion by 5% of their MAX HP each time an enemy inflicts a critical hit.", cooldown: 0, multiplier: null, upgrades: [] }
