        { name: "Unreasoning Outburst", type: "A3", icon: "skill_icons/Galek Ultime_A3.png", description_en: "Attacks all enemies. Has an extra 10% chance of inflicting a critical hit. Has a 75% chance of placing [HP Burn] and [Block Buffs] debuffs for 2 turns.\n\nAlso places a 30% [Decrease SPD] debuff on targets whose Turn Meter is higher than 50%.", cooldown: 4, multiplier: "4.6*ATK", upgrades: ["Lvl. 2 Damage +10%", "Lvl. 3 Buff/Debuff Chance +10%", "Lvl. 4 Buff/Debuff Chance +15%", "Lvl. 5 Cooldown -1"] },
        { name: "Laugh At Danger", type: "Passif", icon: "skill_icons/Galek Ultime_Passif.png", description_en: "Whenever this Champion receives a [Fear], [True Fear], [Freeze], [Provoke], [Sleep], [Stun], or [Petrification] debuff, instantly removes it. Then, fully heals this Champion, and grants an Extra Turn.", cooldown: 0, multiplier: null, upgrades: [] }
