        { name: "Rally the Tribe", type: "A2", icon: "skill_icons/Opardin Chef de Clan_A2.png", description_en: "Attacks all enemies. Heals all allies by 20% of this Champion's MAX HP. Heals all allies under [Continuous Heal] buffs by 30% instead.", cooldown: 4, multiplier: "0.27*HP", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Damage +5%", "Lvl. 4 Heal +10%", "Lvl. 5 Cooldown -1"] },
        { name: "Clan Mentor", type: "A3", icon: "skill_icons/Opardin Chef de Clan_A3.png", description_en: "Removes all [Block Buffs] and [Heal Reduction] debuffs from all allies, then places two 15% [Continuous Heal] buffs and a [Block Debuffs] buff on all allies for 2 turns. Also has a 75% chance of removing 1 random debuff from all allies.", cooldown: 4, multiplier: null, upgrades: ["Lvl. 2 Buff/Debuff Chance +10%", "Lvl. 3 Buff/Debuff Chance +15%", "Lvl. 4 Cooldown -1"] },
        { name: "Paternal", type: "Passif", icon: "skill_icons/Opardin Chef de Clan_Passif.png", description_en: "Each time a [Continuous Heal] buff heals an ally, fills that ally's Turn Meter by 10%.\n\nIf there are multiple Champions in the team with this Skill, only one will activate.", cooldown: 0, multiplier: null, upgrades: [] }
