        { name: "Lay Waste", type: "A2", icon: "skill_icons/Varl le Destructeur_A2.png", description_en: "Attacks all enemies. Has a 75% chance of placing a 25% [Weaken] debuff for 2 turns. Also places a 50% [Decrease ATK] debuff for 2 turns on those enemies who receive a [Weaken] debuff.", cooldown: 4, multiplier: "4*ATK", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Damage +10%", "Lvl. 4 Buff/Debuff Chance +10%", "Lvl. 5 Buff/Debuff Chance +15%", "Lvl. 6 Cooldown -1"] },
        { name: "Calamity Torrent", type: "A3", icon: "skill_icons/Varl le Destructeur_A3.png", description_en: "Attacks 1 enemy. Will ignore 30% of the target’s DEF. Decreases the target’s MAX HP by 50% of the damage inflicted.\n\nPlaces a [Block Damage] buff on this Champion for 1 turn if this attack kills an enemy.", cooldown: 5, multiplier: "5.6*ATK", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Damage +10%", "Lvl. 4 Damage +10%", "Lvl. 5 Cooldown -1"] },
        { name: "Mass Murder", type: "Passif", icon: "skill_icons/Varl le Destructeur_Passif.png", description_en: "Increases this Champion’s ATK by 10% each time they use an Active Skill (stacks up to 100%). Resets each round.", cooldown: 0, multiplier: null, upgrades: [] }
