        { name: "Stance of Steel", type: "A2", icon: "skill_icons/Pegason pourpre_A2.png", description_en: "Places a [Taunt] buff on this Champion for 1 turn.\n\nAlso places a [Shield] buff on all allies for 2 turns, equal to 15% of this Champion’s MAX HP.", cooldown: 6, multiplier: null, upgrades: ["Lvl. 2 Shield +10%", "Lvl. 3 Shield +10%", "Lvl. 4 Cooldown -1", "Lvl. 5 Cooldown -1"] },
        { name: "Military Discipline", type: "Passif", icon: "skill_icons/Pegason pourpre_Passif.png", description_en: "Whenever this Champion is attacked, has a 5% chance of decreasing all incoming damage to zero.", cooldown: 1, multiplier: null, upgrades: ["Lvl. 2 Buff/Debuff Chance +10%", "Lvl. 3 Buff/Debuff Chance +10%"] }
