        { name: "Dead Stop", type: "A2", icon: "skill_icons/Élégaïus_A2.png", description_en: "Attacks 1 enemy. Puts the target's skills on cooldown. Also places a [Block Buffs] debuff for 2 turns.\n\nIf there are any enemy Champions that share the same Affinity as the initial target, also puts all their skills on cooldown and places a [Block Buffs] debuff on them for 2 turns.", cooldown: 4, multiplier: "0.27*HP", upgrades: ["Lvl. 2 Damage +5%", "Lvl. 3 Damage +10%", "Lvl. 4 Cooldown -1"] },
        { name: "Ghost Rage", type: "A3", icon: "skill_icons/Élégaïus_A3.png", description_en: "Attacks all enemies. Has a 75% chance of removing all buffs.\n\nAlso has a 75% chance of decreasing all enemies' Turn Meters by 20%. Decreases each enemy's Turn Meter by an additional 10% for each buff removed.", cooldown: 5, multiplier: "0.2*HP", upgrades: ["Lvl. 2 Buff/Debuff Chance +10%", "Lvl. 3 Damage +10%", "Lvl. 4 Buff/Debuff Chance +15%", "Lvl. 5 Cooldown -1"] },
        { name: "Spurned by Death", type: "Passif", icon: "skill_icons/Élégaïus_Passif.png", description_en: "Prevents this Champion's death and keeps them alive on 1 HP when hit by a fatal hit.\n\nIf this skill prevents this Champion's death, heals them by 30% of their MAX HP, fills their Turn Meter by 30%, and places a [Shield] buff on them equal to 30% of their MAX HP for 2 turns.\n\nWill not prevent this Champion's death if they are under a [Heal Reduction] debuff.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1"] }
