        { name: "Atomize", type: "A2", icon: "skill_icons/Embrys l’Anomalie_A2.png", description_en: "Attacks all enemies.\n\nDeals double damage to enemies whose ACC is lower than this Champion’s ACC. Ignores 50% of each enemy’s DEF whose ACC is equal to or higher than this Champion’s ACC.", cooldown: 4, multiplier: "(0.28 + ACC/10000)*HP", upgrades: ["Lvl. 2 Damage +20%", "Lvl. 3 Cooldown -1"] },
        { name: "The Unmaking", type: "A3", icon: "skill_icons/Embrys l’Anomalie_A3.png", description_en: "Attacks all enemies.\n\nRemoves any [Stone Skin] buffs and replaces them with [True Fear] debuffs. [Block Debuffs] buffs will be replaced with [Block Buffs] debuffs.\n\nAlso removes any buffs positively affecting stats, and replaces them with their mirrored debuff equivalent, such as [Increase ATK] being replaced with [Decrease ATK]. Buffs such as [Continuous Heal] and [Strengthen] will be replaced with [Heal Reduction] and [Weaken] debuffs respectively. The mirrored debuffs will have the same duration as the buffs before they were replaced.\n\nThen steals 5% of each target's Turn Meter for each buff converted into a debuff by this skill. Also decreases the Turn Meters of all enemies by 20%.\n\nThese effects cannot be resisted if enemies have any [Necrosis] stacks.", cooldown: 5, multiplier: "0.27*HP", upgrades: ["Lvl. 2 Ignore RES +20%", "Lvl. 3 Cooldown -1"] },
        { name: "Your Life Is Forfeit!", type: "A3", icon: "skill_icons/Embrys l’Anomalie_A3.png", description_en: "Swaps HP with an enemy. If the target is a Boss, fully restores this Champion’s destroyed MAX HP and fully heals this Champion instead.\n\nEach time this skill is used, increases this Champion’s Ignore DEF effect by 10% while in their Alternate Form (stacks up to 50%).\n\nThen grants an Extra Turn.", cooldown: 5, multiplier: null, upgrades: ["Lvl. 2 Cooldown -1"] },
        { name: "Metamorph", type: "A4", icon: "skill_icons/Embrys l’Anomalie_A4.png", description_en: "Transforms this Champion into their Alternate Form. Then grants an Extra Turn.", cooldown: 4, multiplier: null, upgrades: [] },
        { name: "Metamorph", type: "A4", icon: "skill_icons/Embrys l’Anomalie_A4.png", description_en: "Transforms this Champion into their Base Form. Then grants an Extra Turn.", cooldown: 4, multiplier: null, upgrades: [] },
        { name: "Wrongful Existence", type: "Passif", icon: "skill_icons/Embrys l’Anomalie_Passif.png", description_en: "Whenever an enemy is killed, places one [Necrosis] stack on all other enemies. [Necrosis] stacks cannot be resisted or blocked. [Necrosis] stacks can only be removed by reviving dead allies. This effect does not work against Bosses and their minions. If there are multiple Champions on the team with this skill, this effect will only activate once.\n\nAt the start and the end of this Champion's turn, instantly activates any [Necrosis] stacks on all enemies.", cooldown: 0, multiplier: null, upgrades: [] },
        { name: "Degenerator", type: "Passif", icon: "skill_icons/Embrys l’Anomalie_Passif.png", description_en: "[Passive Effect]\n\nWhen this Champion dies, reflects damage equal to 50% of the fatal hit back to the attacker, including any surplus damage.\n\nWhenever an enemy is killed, places one [Necrosis] stack on all other enemies. [Necrosis] stacks cannot be resisted or blocked. [Necrosis] stacks can only be removed by reviving dead allies. This effect does not apply against Bosses and their minions.\n\nIf there are multiple Champions on the team with this skill, only one will activate. This skill will not activate on duplicate copies of this Champion, if this particular Champion is dead.\n\n[Active Effect]\n\nIf this Champion is about to get killed by a fatal hit, preempts that hit and instantly places a [Revive On Death] buff on them for 1 turn before the damage is taken.", cooldown: 5, multiplier: null, upgrades: [] }
