        { name: "Imbibed Immunity", type: "Passif", icon: "skill_icons/Kosk Deux peaux_Passif.png", description_en: "This Champion is immune to [Poison], [Stun], and [Decrease SPD] debuffs.\n\nIncreases this Champion’s damage dealt by 5% (stacks up to 50%) and Ignore DEF effect by 3% (stacks up to 30%) for each active debuff on the enemy team.\n\nWhenever this Champion is attacked by an enemy under a debuff placed by this Champion, counterattacks using their default skill.", cooldown: 0, multiplier: null, upgrades: [] }
